package com.sigo.asistencia.entity;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="asistencia_registro") @Getter @Setter @NoArgsConstructor @AllArgsConstructor
public class AsistenciaRegistro { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="plaza_id",nullable=false) private Plaza plaza; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="turno_id",nullable=false) private Turno turno; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="controlador_id",nullable=false) private Trabajador controlador; @Column(nullable=false) private LocalDate fecha; @Column(nullable=false) private Integer programados; @Column(nullable=false) private Integer presentes; @Column(insertable=false,updatable=false) private BigDecimal porcentaje; private String notas; @Column(name="created_at",insertable=false,updatable=false) private OffsetDateTime createdAt; @Column(name="updated_at",insertable=false,updatable=false) private OffsetDateTime updatedAt; }
